    output: "$ aws stepfunctions start-execution \\\n    --state-machine-arn arn:aws:states:us-east-1:123456789012:stateMachine:order-flow \\\n    --input '{\"orderId\": \"o-1001\", \"qty\": 2}' --query executionArn\n\"arn:aws:states:us-east-1:123456789012:execution:order-flow:3f1c2a9b-8e7d-4c5b-a3f2-e1d0c9b8a7f6\"\n\n$ aws stepfunctions describe-execution --execution-arn arn:aws:states:...:3f1c2a9b-... \\\n    --query '{status:status,output:output}'\n{\n    \"status\": \"SUCCEEDED\",\n    \"output\": \"{\\\"orderId\\\":\\\"o-1001\\\",\\\"reserved\\\":2,\\\"charged\\\":true}\"\n}",
